47		src := &scriptReader{steps: []scriptStep{
48			// One step: all bytes and io.EOF become available together.
49			{data: []byte(complete + fragment), err: io.EOF},
50		}}
51		var out bytes.Buffer
52		failures, err := NormalizeReader(src, &out)
53		if err != nil {
