116		}
117	
118		// The fault must neither swallow already-delivered complete lines nor
119		// turn them into failures: output must match a healthy read of the very
120		// same complete lines exactly, including order and physical numbers.
121		var healthy bytes.Buffer
122		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(complete), &healthy)
123		if healthyErr != nil || healthyFailures != 1 {
124			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
125		}
