41		fmt.Println("  normalize   read newline-delimited JSON logs from stdin and write")
42		fmt.Println("              normalized event results to stdout, one JSON object per line;")
43		fmt.Println("              exits non-zero when one or more input lines fail")
44		fmt.Println()
45		fmt.Println("              options:")
46		fmt.Println("                --source-cidr <IPv4>/<prefix>")
47		fmt.Println("                    emit a successful event only when its normalized")
48		fmt.Println("                    source_ip lies in this single IPv4 network (prefix")
49		fmt.Println(`                    length 0-32, e.g. "192.0.2.0/24" or "192.0.2.123/24";`)
50		fmt.Println("                    failed lines are still reported. May be given once.")
51		fmt.Println("  version     print the relayproof version")
52		fmt.Println("  help        show this help")
53	}
54	
55	func runNormalize() {
56		// Options are parsed before stdin is read: a malformed option exits 2
57		// with empty stdout, exactly like a stream-level failure, and no log
58		// content is consumed or produced for it.
59		filter, err := parseNormalizeOptions(os.Args[2:])
60		if err != nil {
61			fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
62			os.Exit(2)
63		}
64		failures, err := relayproof.NormalizeReaderFiltered(os.Stdin, os.Stdout, filter)
65		if err != nil {
66			fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
