func decodeAvailable(t *testing.T, data []byte) []map[string]any {
	t.Helper()
	var results []map[string]any
	dec := json.NewDecoder(bytes.NewReader(data))
	for {
		var m map[string]any
		if err := dec.Decode(&m); err != nil {
			return results
		}
		results = append(results, m)
	}
